from typing import Any, Dict, List, Optional
from django.db import models
from audio_events.models import AudioEvent


class PythonPrediction(models.Model):
    """Stores inference predictions generated by the Python ML model service."""

    objects = models.Manager()

    audio_event = models.ForeignKey(
        AudioEvent,
        on_delete=models.CASCADE,
        related_name="python_predictions",
    )
    predicted_class = models.CharField(max_length=64, db_index=True)
    confidence = models.FloatField(
        default=0.0,
        db_index=True,
        help_text="Top predicted class confidence score",
    )
    confidence_scores = models.JSONField(
        help_text="Confidence scores dictionary mapping all sound categories to float confidence values"
    )
    model_version = models.CharField(max_length=64)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        ordering = ["-created_at"]
        indexes = [
            models.Index(fields=["confidence"], name="py_pred_confidence_idx"),
            models.Index(fields=["predicted_class"], name="py_pred_class_idx"),
        ]

    def save(self, *args, **kwargs) -> None:
        if isinstance(self.confidence_scores, dict):
            if self.predicted_class and self.predicted_class in self.confidence_scores:
                self.confidence = float(self.confidence_scores[self.predicted_class])
            elif self.confidence_scores:
                self.confidence = float(max(self.confidence_scores.values()))
        super().save(*args, **kwargs)

    @property
    def top3(self) -> list:
        """Return top 3 predictions as a list of dicts with category, confidence, and percentage."""
        if not isinstance(self.confidence_scores, dict):
            return []
        sorted_scores = sorted(self.confidence_scores.items(), key=lambda x: float(x[1]), reverse=True)[:3]
        return [
            {
                "category": cat,
                "confidence": float(score),
                "confidence_formatted": f"{float(score):.4f}",
                "percentage": round(float(score) * 100),
            }
            for cat, score in sorted_scores
        ]

    def __str__(self) -> str:
        return f"PythonPrediction({self.audio_event.audio_id}: {self.predicted_class})"


