class ComparisonResult(models.Model):
    """Stores comparative analysis metrics between Python model and GTM model predictions."""

    objects = models.Manager()

    MATCH_ACCEPTABLE = "Acceptable Match"
    MATCH_WEAK = "Weak Match"
    MATCH_DISAGREEMENT = "Model Disagreement"
    MATCH_UNCERTAIN = "Uncertain Result"

    MATCH_STATUS_CHOICES = [
        (MATCH_ACCEPTABLE, "Acceptable Match"),
        (MATCH_WEAK, "Weak Match"),
        (MATCH_DISAGREEMENT, "Model Disagreement"),
        (MATCH_UNCERTAIN, "Uncertain Result"),
    ]

    audio_event = models.ForeignKey(
        AudioEvent,
        on_delete=models.CASCADE,
        related_name="comparison_results",
    )
    confidence_difference = models.FloatField(
        help_text="Absolute confidence difference: |Python top confidence - GTM top confidence|"
    )
    top_two_margin = models.FloatField(
        help_text="Margin between top class confidence and second class confidence"
    )
    match_status = models.CharField(
        max_length=64,
        choices=MATCH_STATUS_CHOICES,
        db_index=True,
    )
    is_uncertain = models.BooleanField(default=False, db_index=True)
    is_overlapping = models.BooleanField(default=False)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        ordering = ["-created_at"]

    @property
    def python_prediction(self) -> Any:
        """Return associated PythonPrediction object for the audio event."""
        return self.audio_event.python_predictions.order_by("-created_at").first()

    @property
    def gtm_prediction(self) -> Any:
        """Return associated GTMPrediction object for the audio event."""
        return self.audio_event.gtm_predictions.order_by("-created_at").first()

    @property
    def badge_css_class(self) -> str:
        """Return distinct Tailwind CSS color classes per match status."""
        status_map = {
            self.MATCH_ACCEPTABLE: "bg-emerald-500/20 text-emerald-300 border-emerald-500/40 shadow-emerald-950/20",
            self.MATCH_WEAK: "bg-amber-500/20 text-amber-300 border-amber-500/40 shadow-amber-950/20",
            self.MATCH_DISAGREEMENT: "bg-rose-500/20 text-rose-300 border-rose-500/40 shadow-rose-950/20",
            self.MATCH_UNCERTAIN: "bg-purple-500/20 text-purple-300 border-purple-500/40 shadow-purple-950/20",
        }
        return status_map.get(self.match_status, "bg-slate-700/50 text-slate-300 border-slate-600")

    def __str__(self) -> str:
        return f"ComparisonResult({self.audio_event.audio_id}: {self.match_status})"
